<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\ValueObject\UserPersonalApiKeyCreatedAtVO;

final class UserPersonalApiKeyCreatedAtVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = (new \DateTimeImmutable('1980-08-20T14:32:45.123Z'));
        $ref = UserPersonalApiKeyCreatedAtVO::from($value);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $ref->value());
        $other = UserPersonalApiKeyCreatedAtVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = UserPersonalApiKeyCreatedAtVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = UserPersonalApiKeyCreatedAtVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
        $errors = new ConstraintFailList();
        $other = UserPersonalApiKeyCreatedAtVO::tryFrom(22, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_optimist_asignation_invalid_type(): void
    {
        $this->expectException(ConstraintException::class);
        $method = new ReflectionMethod(UserPersonalApiKeyCreatedAtVO::class, 'fromUnsafe');
        $method->invoke(null, [11, "bad"]);
    }
    public function test_equals(): void
    {
        $one = UserPersonalApiKeyCreatedAtVO::from((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = UserPersonalApiKeyCreatedAtVO::from((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $other = UserPersonalApiKeyCreatedAtVO::from((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));
        $withEmpty = $one->equals(null);
        $withSame = $one->equals($same);
        $withOther = $one->equals($other);

        $this->assertFalse($withEmpty);
        $this->assertTrue($withSame);
        $this->assertFalse($withOther);
    }
    public function test_read_date_format(): void
    {
        $errors = new ConstraintFailList();
        $value = '2024-05-26T14:32:45.123Z';
        $other = UserPersonalApiKeyCreatedAtVO::tryFrom($value, $errors);
        $date = new \DateTimeImmutable($value);
        $this->assertEquals($date, $other->value());
        $this->assertTrue($errors->isEmpty());
        $invalid = '2024-15-26T14:32:45.123Z';
        $other = UserPersonalApiKeyCreatedAtVO::tryFrom($invalid, $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
}
